const DAYS=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
let today='',D={topics:[],sessions:[],rules:[]},R={};
const $=id=>document.getElementById(id);
function ms(s){const p=s.split('-');return Date.UTC(+p[0],+p[1]-1,+p[2]);}
function addDays(s,n){return new Date(ms(s)+n*86400000).toISOString().slice(0,10);}
function wd(s){return new Date(ms(s)).getUTCDay();}
function blocked(extra){const b=new Set(D.rules.map(r=>r.weekday));if(extra!==undefined)b.add(extra);return b;}
function allowedDays(b){const out=[];for(let i=0;i<14;i++){const d=addDays(today,i);if(!b.has(wd(d)))out.push(d);}return out;}
function load(d,sess){return sess.filter(s=>s.date===d).length;}
function msg(id,t,c){const e=$(id);e.textContent=t;e.className='msg '+(c||'');}
async function refresh(){const r=await tessera.call('data.read',{});D.topics=r.data.topics||[];D.sessions=r.data.sessions||[];D.rules=r.data.rules||[];R=r.revisions||{};render();}
function render(){
 const rl=$('rules');rl.textContent='';
 if(!D.rules.length){const li=document.createElement('li');li.textContent='No rules: every weekday can be used.';rl.appendChild(li);}
 for(const r of D.rules){const li=document.createElement('li');li.setAttribute('data-hook','rule');
 const sp=document.createElement('span');sp.textContent='Never on '+DAYS[r.weekday]+'s';
 const b=document.createElement('button');b.type='button';b.className='sec';b.setAttribute('data-hook','rule-remove');b.textContent='Remove';b.setAttribute('aria-label','Remove rule: never on '+DAYS[r.weekday]+'s');
 b.addEventListener('click',()=>removeRule(r.id));li.append(sp,b);rl.appendChild(li);}
 const pl=$('plan');pl.textContent='';
 const names={};for(const t of D.topics)names[t.id]=t.name;
 const ss=D.sessions.filter(s=>names[s.topicId]!==undefined).sort((a,b)=>a.date<b.date?-1:a.date>b.date?1:0);
 $('empty').textContent=ss.length?'':'No topics yet. Add your first topic above and it will be scheduled for you.';
 for(const s of ss){const li=document.createElement('li');li.setAttribute('data-hook','session');
 const left=document.createElement('span');
 const t=document.createElement('time');t.setAttribute('datetime',s.date);t.textContent=DAYS[wd(s.date)]+' '+s.date;
 const ev=document.createElement('span');ev.className='when';ev.textContent=' · evening · ';
 const n=document.createElement('strong');n.style.fontWeight='400';n.setAttribute('data-hook','session-task');n.textContent=names[s.topicId];
 left.append(t,ev,n);li.appendChild(left);pl.appendChild(li);}
 if(D.topics.length){const h=document.createElement('li');h.style.display='block';const p=document.createElement('p');p.className='hint';p.textContent='Topics: ';p.style.margin='0';
 for(const t of D.topics){const b=document.createElement('button');b.type='button';b.className='sec';b.textContent='Remove '+t.name;b.style.margin='2px';b.addEventListener('click',()=>removeTopic(t.id,t.name));p.appendChild(b);}
 h.appendChild(p);pl.appendChild(h);}
}
async function addTopic(){
 const name=$('tn').value.trim();
 if(!name){msg('tmsg','Type a topic name first.','err');return;}
 const b=blocked(),days=allowedDays(b);
 if(!days.length){msg('tmsg','Every day is ruled out, so nothing can be scheduled. Remove a rule first.','err');return;}
 try{
 const sess=D.sessions.slice();const picks=[];
 const pick=(cands)=>{let best=null,bl=1e9;for(const d of cands){const l=load(d,sess);if(l<bl){bl=l;best=d;}}return best;};
 const first=pick(days.slice(0,Math.ceil(days.length/2)));sess.push({date:first});picks.push(first);
 if(days.length>1){const far=days.filter(d=>Math.abs(ms(d)-ms(first))>=4*86400000);const second=pick(far.length?far:days.filter(d=>d!==first));if(second)picks.push(second);}
 const r=await tessera.call('data.patch',{operations:[{op:'add',collection:'topics',record:{name:name}}]});
 const id=r.addedIds[0];
 await tessera.call('data.patch',{operations:picks.map(d=>({op:'add',collection:'sessions',record:{topicId:id,date:d}}))});
 $('tn').value='';await refresh();msg('tmsg','Added "'+name+'" with '+picks.length+' evening session'+(picks.length>1?'s':'')+'.','ok');
 }catch(e){msg('tmsg','Could not add the topic. Your text is still here; try again.','err');try{await refresh();}catch(x){}}
}
async function removeTopic(id,name){
 try{const ops=D.sessions.filter(s=>s.topicId===id).map(s=>({op:'remove',collection:'sessions',id:s.id,revisionCount:R.sessions[s.id]}));
 ops.push({op:'remove',collection:'topics',id:id,revisionCount:R.topics[id]});
 await tessera.call('data.patch',{operations:ops});await refresh();msg('tmsg','Removed "'+name+'" and its sessions.','ok');
 }catch(e){msg('tmsg','Could not remove the topic.','err');}
}
async function addRule(){
 const day=+$('rd').value;
 const b=blocked(day);
 if(b.size>=7){msg('rmsg','You need at least one day to study. This rule was not added.','err');return;}
 const days=allowedDays(b);
 if(!days.length){msg('rmsg','That rule would leave no days in the next two weeks. It was not added.','err');return;}
 try{
 const ops=[{op:'add',collection:'rules',record:{weekday:day}}];
 let sess=D.sessions.map(s=>({id:s.id,topicId:s.topicId,date:s.date}));
 let moved=0;
 for(const s of sess.filter(x=>wd(x.date)===day)){
 const mine=sess.filter(x=>x.topicId===s.topicId&&x!==s);
 const free=days.filter(d=>!mine.some(m=>m.date===d));
 if(free.length){let best=null,bl=1e9;for(const d of free){const l=load(d,sess);if(l<bl){bl=l;best=d;}}
 s.date=best;ops.push({op:'replace',collection:'sessions',id:s.id,revisionCount:R.sessions[s.id],fields:{date:best}});}
 else if(mine.length){s.gone=true;sess=sess.filter(x=>x!==s);ops.push({op:'remove',collection:'sessions',id:s.id,revisionCount:R.sessions[s.id]});}
 moved++;}
 await tessera.call('data.patch',{operations:ops});await refresh();
 msg('rmsg','Rule added: no studying on '+DAYS[day]+'s. '+moved+' session'+(moved===1?'':'s')+' moved.','ok');
 }catch(e){msg('rmsg','Could not add the rule.','err');try{await refresh();}catch(x){}}
}
async function removeRule(id){
 try{await tessera.call('data.patch',{operations:[{op:'remove',collection:'rules',id:id,revisionCount:R.rules[id]}]});await refresh();msg('rmsg','Rule removed. Existing sessions stay where they are.','ok');
 }catch(e){msg('rmsg','Could not remove the rule.','err');}
}
$('ta').addEventListener('click',addTopic);
$('tn').addEventListener('keydown',e=>{if(e.key==='Enter')addTopic();});
$('ra').addEventListener('click',addRule);
(async()=>{try{const c=await tessera.call('clock.now',{});today=c.date;await refresh();}catch(e){msg('tmsg','Could not load your plan.','err');}})();

